flow.set('lastTx', { topic: msg.topic, at: Date.now() });
node.status({ text: 'TX ' + msg.topic });
node.send([msg, { payload: 'TX ' + msg.topic + ': ' + msg.payload.toString('hex').match(/../g).join(' ') }]);

// Accept whatever the serial node delivers: Buffer, string, byte array or anything else
const raw = msg.payload;
let b = null;
if (Buffer.isBuffer(raw)) b = raw;
else if (typeof raw === 'string') b = Buffer.from(raw, 'latin1');
else if (Array.isArray(raw)) b = Buffer.from(raw);
const tx = flow.get('lastTx') || {};
const ms = tx.at ? (Date.now() - tx.at) + ' ms after ' + tx.topic : '';
if (!b) {
  node.status({ fill: 'red', shape: 'ring', text: 'non-binary payload: ' + typeof raw });
  msg.payload = 'RX non-binary payload (' + typeof raw + '), check the serial config node: ' + JSON.stringify(raw) + (ms ? ', ' + ms : '');
  return msg;
}
const note = Buffer.isBuffer(raw) ? '' : ' (arrived as ' + (Array.isArray(raw) ? 'array' : 'string') + ': set Output to binary buffers)';
const hex = b.length ? b.toString('hex').match(/../g).join(' ') : '';
let kind = 'unknown';
if (b[0] === 0xEB && b[1] === 0x90) kind = 'V1.3 reply EB 90';
else if (b[0] === 0x55 && b[1] === 0xAA && b[2] === 0xEB && b[3] === 0x90) kind = 'JK02 frame type 0x' + b[4].toString(16).padStart(2, '0');
else if (b[0] === 0xAA && b[1] === 0x55 && b[2] === 0x90 && b[3] === 0xEB) kind = 'JK02 command/ready 0x' + b[4].toString(16).padStart(2, '0');
let sumOk = false;
if (b.length > 1) {
  let sum = 0;
  for (let i = 0; i < b.length - 1; i++) sum += b[i];
  sumOk = (sum & 0xFF) === b[b.length - 1];
}
node.status({ text: b.length + ' B, ' + kind });
msg.payload = 'RX ' + b.length + ' bytes, ' + kind + ', checksum ' + (sumOk ? 'ok' : 'no') + (ms ? ', ' + ms : '') + note + ':\n' + hex;
return msg;
